// FIXED: ESLint + TS without hacks

import * as Yup from 'yup';
import { useEffect, useMemo, useRef, useState } from 'react';
import { useForm, FormProvider as RHFProvider } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';

import Link from '@mui/material/Link';
import Alert from '@mui/material/Alert';
import Stack from '@mui/material/Stack';
import IconButton from '@mui/material/IconButton';
import Typography from '@mui/material/Typography';
import LoadingButton from '@mui/lab/LoadingButton';
import InputAdornment from '@mui/material/InputAdornment';

import Dialog from '@mui/material/Dialog';
import DialogTitle from '@mui/material/DialogTitle';
import DialogContent from '@mui/material/DialogContent';
import DialogActions from '@mui/material/DialogActions';
import DialogContentText from '@mui/material/DialogContentText';
import Button from '@mui/material/Button';

import axios, { endpoints } from 'src/utils/axios';

import { useTranslate } from 'src/locales';
import { paths } from 'src/routes/paths';
import { RouterLink } from 'src/routes/components';
import { useRouter, useSearchParams } from 'src/routes/hooks';

import { useBoolean } from 'src/hooks/use-boolean';
import { useAuthContext } from 'src/auth/hooks';
import { PATH_AFTER_LOGIN } from 'src/config-global';

import Iconify from 'src/components/iconify';
import FormProvider, { RHFTextField, RHFPhoneField } from 'src/components/hook-form';
import { useSnackbar } from 'src/components/snackbar';

// ----------------------------------------------------------------------

type ErrorResponse = {
  response?: {
    data?:
      | string
      | string[]
      | {
          error: any;
          detail?: string;
          phone?: string[];
          non_field_errors?: string[];
        };
    error?: string | string[] | { detail?: string };
  };
};

type ForgotFormShape = {
  f_email: string;
  f_otp?: string;
  f_password?: string;
  f_password2?: string;
};

export default function JwtLoginView() {
  const { login, forgot_password } = useAuthContext();
  const { t } = useTranslate();
  const router = useRouter();

  const [errorMsg, setErrorMsg] = useState('');

  const searchParams = useSearchParams();
  const returnTo = searchParams.get('returnTo');

  const password = useBoolean();

  // ====== LOGIN ======
  const LoginSchema = Yup.object({
    password: Yup.string().required(t('auth.passwordRequired')),
  });

  const defaultValues = { phone: '', password: '' };

  const methods = useForm({
    resolver: yupResolver(LoginSchema),
    defaultValues,
  });

  const {
    reset,
    handleSubmit,
    formState: { isSubmitting },
  } = methods;

  function extractErrorMessage(error: ErrorResponse): string {
    const data = error.response?.data;
    if (data) {
      if (typeof data === 'string') return data;
      if (Array.isArray(data)) return data[0];
      if (typeof data === 'object') {
        if (data.error) return data.error;
        if (data.detail) return data.detail;
        if (data.phone?.length) return data.phone[0];
        if (data.non_field_errors?.length) return t(`error.${data.non_field_errors[0]}`);
      }
    }
    const errData = error.response?.error;
    if (errData) {
      if (typeof errData === 'string') return errData;
      if (Array.isArray(errData)) return errData[0];
      if (typeof errData === 'object' && errData.detail) return errData.detail;
    }
    return 'An error occurred. Please try again.';
  }

  const onSubmit = handleSubmit(async (data: any) => {
    if (!data?.phone || data?.phone === '') {
      setErrorMsg(t('auth.phoneRequired'));
    } else {
      try {
        await login?.(data);
        router.push(returnTo || PATH_AFTER_LOGIN);
      } catch (error: any) {
        reset();
        setErrorMsg(extractErrorMessage(error) || t('errorOccurred'));
      }
    }
  });

  // ====== FORGOT PASSWORD MODAL ======
  type ForgotSteps = 'enterPhone' | 'confirmPhone' | 'otp';
  const forgotOpen = useBoolean(false);
  const [step, setStep] = useState<ForgotSteps>('enterPhone');

  const ForgotSchema: Yup.ObjectSchema<ForgotFormShape> = Yup.object({
    f_email: Yup.string().required(t('auth.emailRequired')),
    f_otp: Yup.string().when('$isOtp', {
      is: true,
      then: (s) => s.matches(/^\d{6}$/, t('auth.otpRequired')),
      otherwise: (s) => s.notRequired(),
    }),
    f_password: Yup.string()
      .min(6, t('auth.passwordMin'))
      .when('$isOtp', {
        is: true,
        then: (s) =>
          s.when('f_otp', {
            is: (v: string) => /^\d{6}$/.test(v || ''),
            then: (ss) => ss.required(t('auth.passwordRequired')),
            otherwise: (ss) => ss.notRequired(),
          }),
        otherwise: (s) => s.notRequired(),
      }),
    f_password2: Yup.string()
      .oneOf([Yup.ref('f_password')], t('auth.passwordNotMatch'))
      .when('$isOtp', {
        is: true,
        then: (s) =>
          s.when('f_otp', {
            is: (v: string) => /^\d{6}$/.test(v || ''),
            then: (ss) => ss.required(t('auth.confirmPasswordRequired')),
            otherwise: (ss) => ss.notRequired(),
          }),
        otherwise: (s) => s.notRequired(),
      }),
  });

  const forgotMethods = useForm<ForgotFormShape>({
    resolver: yupResolver(ForgotSchema, { context: { isOtp: step === 'otp' } }),
    defaultValues: { f_email: '', f_otp: '', f_password: '', f_password2: '' },
    mode: 'onChange',
  });

  const {
    handleSubmit: handleForgotSubmit,
    trigger,
    getValues,
    reset: resetForgot,
    formState: { isSubmitting: isForgotSubmitting },
  } = forgotMethods;

  // countdown 5 minutes after resend
  const [deadline, setDeadline] = useState<number | null>(null);
  const [remaining, setRemaining] = useState(0);
  const timerRef = useRef<number | null>(null);

  useEffect(() => {
    // clear any existing timer first
    if (timerRef.current) {
      window.clearInterval(timerRef.current);
      timerRef.current = null;
    }

    if (!deadline) {
      setRemaining(0);
      // always return a cleanup to keep returns consistent
      return () => {};
    }

    timerRef.current = window.setInterval(() => {
      const diff = Math.max(0, Math.floor((deadline - Date.now()) / 1000));
      setRemaining(diff);
      if (diff === 0 && timerRef.current) {
        window.clearInterval(timerRef.current);
        timerRef.current = null;
      }
    }, 1000);

    return () => {
      if (timerRef.current) {
        window.clearInterval(timerRef.current);
        timerRef.current = null;
      }
    };
  }, [deadline]);

  const mmss = useMemo(() => {
    const mm = String(Math.floor(remaining / 60)).padStart(2, '0');
    const ss = String(remaining % 60).padStart(2, '0');
    return `${mm}:${ss}`;
  }, [remaining]);

  const handleForgotClose = () => {
    forgotOpen.onFalse();
    setStep('enterPhone');
    setDeadline(null);
    setRemaining(0);
    resetForgot();
  };

  const handleForgotNext = async () => {
    const ok = await trigger('f_email');
    if (ok) {
      setStep('confirmPhone');
    }
  };
  const { enqueueSnackbar } = useSnackbar();
  const [sendingOtp, setSendingOtp] = useState(false);

  const otpValue = forgotMethods.watch('f_otp') || '';
  const otpDigits = otpValue.replace(/\D/g, '');
  const showPasswords = otpDigits.length === 6;

  const handleForgotConfirmEmail = async () => {
    setSendingOtp(true);
    try {
      const email = getValues('f_email');
      const { data } = await axios.post(endpoints.auth.send_otp, { email });

      setDeadline(Date.now() + 5 * 60 * 1000);
      setStep('otp');

      enqueueSnackbar(data?.message || t('verification.confirmationCode') || 'OTP sent', {
        variant: 'success',
      });
    } catch (error: any) {
      const msg = extractErrorMessage(error);
      setErrorMsg(msg);
      enqueueSnackbar(msg, { variant: 'error' });
    } finally {
      setSendingOtp(false); // stop loading in all cases
    }
  };

  const onSubmitForgot = handleForgotSubmit(async (data) => {
    try {
      await forgot_password?.({
        email: data.f_email,
        otp: String(data.f_otp),
        password: String(data.f_password),
      });

      enqueueSnackbar(t('auth.passwordChanged') || 'Password changed successfully', {
        variant: 'success',
      });

      handleForgotClose();
    } catch (error: any) {
      const msg = extractErrorMessage(error);
      setErrorMsg(msg);
      enqueueSnackbar(msg, { variant: 'error' });
    }
  });

  const renderHead = (
    <Stack spacing={2} sx={{ mb: 5 }}>
      <Typography variant="h4">{t('auth.signInTitle')}</Typography>
      <Stack direction="row" spacing={0.5}>
        <Typography variant="body2">{t('auth.newOnPlatform')}</Typography>
        <Link component={RouterLink} href={paths.auth.jwt.register} variant="subtitle2">
          {t('auth.createAccount')}
        </Link>
      </Stack>
    </Stack>
  );

  const renderForm = (
    <Stack spacing={2.5}>
      <RHFPhoneField name="phone" label={t('auth.phone')} />
      <RHFTextField
        name="password"
        label={t('auth.password')}
        type={password.value ? 'text' : 'password'}
        InputProps={{
          endAdornment: (
            <InputAdornment position="end">
              <IconButton onClick={password.onToggle} edge="end">
                <Iconify icon={password.value ? 'solar:eye-bold' : 'solar:eye-closed-bold'} />
              </IconButton>
            </InputAdornment>
          ),
        }}
      />
      <Link
        variant="body2"
        color="inherit"
        underline="always"
        sx={{ alignSelf: 'flex-end', cursor: 'pointer' }}
        onClick={forgotOpen.onTrue}
      >
        {t('auth.forgotPassword')}
      </Link>
      <LoadingButton
        fullWidth
        color="primary"
        size="large"
        type="submit"
        variant="contained"
        loading={isSubmitting}
      >
        {t('auth.login')}
      </LoadingButton>
    </Stack>
  );

  return (
    <>
      {renderHead}

      {!!errorMsg && (
        <Alert severity="error" sx={{ mb: 3 }}>
          {errorMsg}
        </Alert>
      )}

      <FormProvider methods={methods} onSubmit={onSubmit}>
        {renderForm}
      </FormProvider>

      {/* ===== Forgot Password Modal ===== */}
      <RHFProvider {...forgotMethods}>
        <Dialog open={forgotOpen.value} onClose={handleForgotClose} maxWidth="xs" fullWidth>
          <DialogTitle>{t('auth.forgotPassword')}</DialogTitle>

          {step === 'enterPhone' && (
            <>
              <DialogContent>
                <Stack spacing={2}>
                  <RHFTextField name="f_email" label={t('layout.email')} type="email" />
                </Stack>
              </DialogContent>
              <DialogActions sx={{ px: 3, pb: 2 }}>
                <Button onClick={handleForgotClose}>{t('common.cancel') || 'Annuler'}</Button>
                <LoadingButton onClick={handleForgotNext} variant="contained">
                  {t('common.next') || 'Suivant'}
                </LoadingButton>
              </DialogActions>
            </>
          )}

          {step === 'confirmPhone' && (
            <>
              <DialogContent>
                <DialogContentText>
                  {t('auth.verifyPhone') || 'Vérifier le numéro'}: <b>{getValues('f_email')}</b>
                </DialogContentText>
              </DialogContent>
              <DialogActions sx={{ px: 3, pb: 2, gap: 1 }}>
                <Button onClick={() => setStep('enterPhone')}>
                  {t('common.edit') || 'Modifier'}
                </Button>
                <LoadingButton
                  onClick={handleForgotConfirmEmail}
                  variant="contained"
                  loading={sendingOtp}
                  disabled={sendingOtp}
                >
                  {t('common.confirm') || 'Confirmer'}
                </LoadingButton>
              </DialogActions>
            </>
          )}

          {step === 'otp' && (
            <form onSubmit={onSubmitForgot}>
              <DialogContent sx={{ pt: 1 }}>
                <Stack spacing={2}>
                  <Typography variant="caption" sx={{ alignSelf: 'flex-end' }}>
                    {t('auth.otpExpiresIn') || 'Expire dans'}: {mmss}
                  </Typography>

                  <RHFTextField
                    name="f_otp"
                    label={t('auth.otp') || 'OTP'}
                    inputProps={{ inputMode: 'numeric', maxLength: 6, pattern: '[0-9]*' }}
                  />

                  {showPasswords && (
                    <>
                      <RHFTextField
                        name="f_password"
                        label={t('auth.newPassword')}
                        type="password"
                      />
                      <RHFTextField
                        name="f_password2"
                        label={t('auth.confirmPassword')}
                        type="password"
                      />
                    </>
                  )}
                </Stack>
              </DialogContent>

              <DialogActions sx={{ px: 3, pb: 2 }}>
                <Button onClick={handleForgotClose}>{t('common.cancel') || 'Annuler'}</Button>
                <LoadingButton
                  type="submit"
                  variant="contained"
                  loading={isForgotSubmitting}
                  disabled={!showPasswords}
                >
                  {t('auth.change') || 'Changer'}
                </LoadingButton>
              </DialogActions>
            </form>
          )}
        </Dialog>
      </RHFProvider>
    </>
  );
}
