import * as Yup from 'yup';
import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';

import Link from '@mui/material/Link';
import Alert from '@mui/material/Alert';
import Stack from '@mui/material/Stack';
import IconButton from '@mui/material/IconButton';
import Typography from '@mui/material/Typography';
import LoadingButton from '@mui/lab/LoadingButton';
import InputAdornment from '@mui/material/InputAdornment';
import { useTranslate } from 'src/locales';
import { paths } from 'src/routes/paths';
import { RouterLink } from 'src/routes/components';
import { useRouter, useSearchParams } from 'src/routes/hooks';

import { useBoolean } from 'src/hooks/use-boolean';

import { useAuthContext } from 'src/auth/hooks';
import { PATH_AFTER_LOGIN } from 'src/config-global';

import Iconify from 'src/components/iconify';
import FormProvider, { RHFTextField, RHFPhoneField, RHFCheckbox } from 'src/components/hook-form';

// ----------------------------------------------------------------------

export default function JwtRegisterView() {
  const { t } = useTranslate();
  const { register } = useAuthContext();

  const router = useRouter();

  const [errorMsg, setErrorMsg] = useState('');

  const searchParams = useSearchParams();

  const returnTo = searchParams.get('returnTo');

  const password = useBoolean();

  const RegisterSchema = Yup.object().shape({
    phone: Yup.string().required(t('auth.phoneRequired')),
    email: Yup.string().email(t('auth.emailRequired')),
    country: Yup.string().required(),
    password: Yup.string().required(t('auth.passwordRequired')),
    confirmPassword: Yup.string()
      .oneOf([Yup.ref('password'), undefined], t('auth.passwordsMustMatch'))
      .required(t('auth.confirmPasswordRequired')),
    acceptTerms: Yup.boolean()
      .oneOf([true], t('auth.acceptTermsRequired'))
      .required(t('auth.acceptTermsRequired')),
  });

  const defaultValues = {
    phone: '',
    email: '',
    password: '',
    country: 'CL',
    confirmPassword: '',
    acceptTerms: false,
  };
  type RegisterFormValues = {
    phone: string;
    email?: string;
    password: string;
    country: string;
    confirmPassword: string;
    acceptTerms: boolean;
  };

  const methods = useForm<RegisterFormValues>({
    resolver: yupResolver(RegisterSchema),
    defaultValues,
  });

  const {
    reset,
    handleSubmit,
    setValue,
    formState: { isSubmitting },
  } = methods;

  type ErrorResponse = {
    response?: {
      data?: string | string[] | { detail?: string; phone?: string[] };
      error?: string | string[] | { detail?: string };
    };
  };

  function extractErrorMessage(error: ErrorResponse): string {
    // Check if `response` and `data` exist
    if (error.response?.data) {
      const { data } = error.response;

      if (typeof data === 'string') {
        return data;
      }

      if (Array.isArray(data)) {
        return data[0];
      }

      if (data.detail) {
        return data.detail;
      }

      if (data.phone?.length) {
        return data.phone[0];
      }
    }

    // Check if `response` and `error` exist
    if (error.response?.error) {
      const { error: errData } = error.response;

      if (typeof errData === 'string') {
        return errData;
      }

      if (Array.isArray(errData)) {
        return errData[0];
      }

      if (errData.detail) {
        return errData.detail;
      }
    }

    // Default fallback error message
    return 'An error occurred. Please try again.';
  }

  const onSubmit = handleSubmit(async (data: any) => {
    if (!data?.phone || data?.phone === '') {
      setErrorMsg(t('auth.phoneRequired'));
      return;
    }
    try {
      await register?.(data);

      router.push(returnTo || PATH_AFTER_LOGIN);
    } catch (error) {
      console.error(error);
      reset();
      setErrorMsg(extractErrorMessage(error) || t('errorOccurred'));
    }
  });

  const renderHead = (
    <Stack spacing={2} sx={{ mb: 2, position: 'relative' }}>
      <Typography variant="h4">{t('auth.getStarted')}</Typography>

      <Stack direction="row" spacing={0.5}>
        <Typography variant="body2"> {t('auth.alreadyHaveAccount')} </Typography>

        <Link href={paths.auth.jwt.login} component={RouterLink} variant="subtitle2">
          {t('auth.signIn')}
        </Link>
      </Stack>
    </Stack>
  );

  const renderTerms = (
    <Typography
      component="div"
      sx={{
        mt: 2.5,
        textAlign: 'center',
        typography: 'caption',
        color: 'text.secondary',
      }}
    >
      {`${t('auth.bySigningUp')} `}
      <Link underline="always" color="text.primary">
        {t('auth.termsOfService')}
      </Link>
      {' & '}
      <Link underline="always" color="text.primary">
        {t('auth.privacyPolicy')}
      </Link>
      .
    </Typography>
  );

  const renderForm = (
    <Stack spacing={2}>
      <RHFPhoneField
        name="phone"
        label={t('auth.phone')}
        onCountryChange={(code) => setValue('country', code)}
      />

      <RHFTextField name="email" label="Email" type="email" />

      <RHFTextField
        name="password"
        label={t('auth.password')}
        type={password.value ? 'text' : 'password'}
        InputProps={{
          endAdornment: (
            <InputAdornment position="end">
              <IconButton onClick={password.onToggle} edge="end">
                <Iconify icon={password.value ? 'solar:eye-bold' : 'solar:eye-closed-bold'} />
              </IconButton>
            </InputAdornment>
          ),
        }}
      />

      <RHFTextField
        name="confirmPassword"
        label={t('auth.confirmPassword')}
        type={password.value ? 'text' : 'password'}
        InputProps={{
          endAdornment: (
            <InputAdornment position="end">
              <IconButton onClick={password.onToggle} edge="end">
                <Iconify icon={password.value ? 'solar:eye-bold' : 'solar:eye-closed-bold'} />
              </IconButton>
            </InputAdornment>
          ),
        }}
      />

      <RHFCheckbox name="acceptTerms" label={t('auth.acceptTerms')} />

      <LoadingButton
        fullWidth
        color="primary"
        size="large"
        type="submit"
        variant="contained"
        loading={isSubmitting}
      >
        {t('auth.createAccount')}
      </LoadingButton>
    </Stack>
  );

  return (
    <>
      {renderHead}

      {errorMsg ? (
        <Alert severity="error" sx={{ mb: 3 }}>
          {errorMsg}
        </Alert>
      ) : (
        <></>
        // <Alert severity="info" sx={{ mb: 3 }}>
        //   {t('auth.message_check_number')}
        // </Alert>
      )}

      <FormProvider methods={methods} onSubmit={onSubmit}>
        {renderForm}
      </FormProvider>

      {renderTerms}
    </>
  );
}
